import { createRoot } from '@wordpress/element';
import Waves from './components/Waves'; // Verifique se o caminho está exato

const WavesHero = () => {
    if (typeof Waves === 'undefined') {
        console.error("Erro: O componente Waves não foi carregado corretamente.");
        return null;
    }

    return (
        <Waves
            lineColor="#ff7b3b"
            backgroundColor="transparent"
            waveSpeedX={0.025}
            waveSpeedY={0.035}
            waveAmpX={30}
            waveAmpY={10}
            friction={0.71}
            tension={0.035}
            maxCursorMove={100}
            xGap={8}
            yGap={42}
        />
    );
};

// Renderização
const container = document.getElementById('waves-root');
if (container) {
    createRoot(container).render(<WavesHero />);
}